package jsonord

import (
	"bytes"
	"encoding/base64"
	"encoding/json"
	"math"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
)

// pycases.json is generated by testdata/gen_pycases.py (Python 3.12 json.loads / json.dumps(ensure_ascii=False,
// indent=2)).
type pyCases struct {
	Cases []struct {
		In  string  `json:"in"`
		Out *string `json:"out"`
	} `json:"cases"`
	Floats []struct {
		Hex  string `json:"hex"`
		Repr string `json:"repr"`
	} `json:"floats"`
}

func loadPyCases(t *testing.T) pyCases {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("testdata", "pycases.json"))
	if err != nil {
		t.Fatal(err)
	}
	var c pyCases
	if err := json.Unmarshal(data, &c); err != nil {
		t.Fatal(err)
	}
	return c
}

func TestAgainstPython(t *testing.T) {
	c := loadPyCases(t)
	if len(c.Cases) < 50 {
		t.Fatalf("only %d cases", len(c.Cases))
	}
	for i, tc := range c.Cases {
		in, err := base64.StdEncoding.DecodeString(tc.In)
		if err != nil {
			t.Fatal(err)
		}
		show := string(in)
		if len(show) > 60 {
			show = show[:60] + "..."
		}
		v, err := Parse(in)
		if tc.Out == nil {
			if err == nil {
				t.Errorf("case %d %q: Python refuses it, Parse accepted: %s", i, show, v.MarshalPython())
			}
			continue
		}
		if err != nil {
			t.Errorf("case %d %q: Parse: %v", i, show, err)
			continue
		}
		if got := string(v.MarshalPython()); got != *tc.Out {
			t.Errorf("case %d %q:\n got %q\nwant %q", i, show, got, *tc.Out)
		}
		// Clone and a second round trip change nothing.
		if got := string(v.Clone().MarshalPython()); got != *tc.Out {
			t.Errorf("case %d clone: %q", i, got)
		}
		v2, err := Parse(v.MarshalPython())
		if err != nil {
			t.Errorf("case %d reparse: %v", i, err)
		} else if got := string(v2.MarshalPython()); got != *tc.Out {
			t.Errorf("case %d reparse: %q", i, got)
		}
	}
}

func TestPythonFloat(t *testing.T) {
	c := loadPyCases(t)
	if len(c.Floats) < 1000 {
		t.Fatalf("only %d floats", len(c.Floats))
	}
	for _, tc := range c.Floats {
		f, err := strconv.ParseFloat(tc.Hex, 64)
		if err != nil {
			t.Fatalf("%s: %v", tc.Hex, err)
		}
		if got := PythonFloat(f); got != tc.Repr {
			t.Errorf("%s: got %s want %s", tc.Hex, got, tc.Repr)
		}
		if got := string(NewFloat(f).MarshalPython()); got != tc.Repr {
			t.Errorf("NewFloat %s: got %s want %s", tc.Hex, got, tc.Repr)
		}
	}
	for f, want := range map[float64]string{
		math.NaN(): "NaN", math.Inf(1): "Infinity", math.Inf(-1): "-Infinity", 0: "0.0", math.Copysign(0, -1): "-0.0",
		6144: "6144.0", 1e16: "1e+16", 1e15: "1000000000000000.0", 1e-5: "1e-05", 0.0001: "0.0001",
	} {
		if got := PythonFloat(f); got != want {
			t.Errorf("PythonFloat(%v) = %s, want %s", f, got, want)
		}
	}
}

// python is the Python 3 for the live comparisons: $MODAVD_TEST_PYTHON, otherwise python on PATH; the test is skipped
// without one.
func python(t *testing.T) string {
	t.Helper()
	p := os.Getenv("MODAVD_TEST_PYTHON")
	if p == "" {
		found, err := exec.LookPath("python")
		if err != nil {
			t.Skipf("no python on PATH (set MODAVD_TEST_PYTHON): %v", err)
		}
		p = found
	}
	if _, err := os.Stat(p); err != nil {
		t.Skipf("no Python at %s", p)
	}
	return p
}

// TestRoundTripProductionMetadata: a copy of the production mas-avd.json, parsed and written back, is exactly what
// Python writes for json.load of the same copy.
func TestRoundTripProductionMetadata(t *testing.T) {
	src := `D:\ModAVD\mas-avd.json`
	if p := os.Getenv("MODAVD_TEST_METADATA"); p != "" {
		src = p
	}
	data, err := os.ReadFile(src)
	if err != nil {
		t.Skipf("no %s: %v", src, err)
	}
	py := python(t)
	dir := t.TempDir()
	copyPath := filepath.Join(dir, "mas-avd.json")
	if err := os.WriteFile(copyPath, data, 0o644); err != nil {
		t.Fatal(err)
	}
	outPath := filepath.Join(dir, "py.json")
	script := `import json,sys
d=json.load(open(sys.argv[1],encoding="utf-8-sig"))
open(sys.argv[2],"wb").write(json.dumps(d,ensure_ascii=False,indent=2).encode("utf-8"))`
	if out, err := exec.Command(py, "-I", "-c", script, copyPath, outPath).CombinedOutput(); err != nil {
		t.Fatalf("python: %v %s", err, out)
	}
	want, err := os.ReadFile(outPath)
	if err != nil {
		t.Fatal(err)
	}
	v, err := Parse(data)
	if err != nil {
		t.Fatal(err)
	}
	if got := v.MarshalPython(); !bytes.Equal(got, want) {
		t.Fatalf("round trip differs:\n got %q\nwant %q", got, want)
	}
	// AUTO-MAS wrote the file through Python text mode on Windows: the file is the same bytes with CRLF.
	if crlf := bytes.ReplaceAll(want, []byte("\n"), []byte("\r\n")); bytes.Contains(data, []byte("\r\n")) &&
		!bytes.Equal(crlf, data) {
		t.Logf("note: production file is not exactly Python's CRLF output (edited by hand or another tool?)")
	}
}

func TestParseErrorsAreChineseWithPosition(t *testing.T) {
	_, err := Parse([]byte("{\n  \"a\": 1,\n  \"b\" 2\n}"))
	if err == nil {
		t.Fatal("no error")
	}
	if msg := err.Error(); !strings.Contains(msg, "缺少 ':'") || !strings.Contains(msg, "第 3 行第 7 列") {
		t.Fatalf("message: %s", msg)
	}
	_, err = Parse([]byte(`["中文" x]`))
	if err == nil || !strings.Contains(err.Error(), "第 1 行第 7 列，第 6 个字符") {
		t.Fatalf("columns count characters: %v", err)
	}
	_, err = Parse([]byte("{} x"))
	if err == nil || !strings.Contains(err.Error(), "多余") {
		t.Fatalf("trailing garbage: %v", err)
	}
	_, err = Parse([]byte("\xef\xbb\xbf{\"a\": \"\xff\"}"))
	if err == nil || !strings.Contains(err.Error(), "UTF-8") {
		t.Fatalf("bad utf-8: %v", err)
	}
}

func TestBOMAndDuplicates(t *testing.T) {
	v, err := Parse([]byte("\xef\xbb\xbf{\"a\": 1, \"b\": 2, \"a\": {\"x\": []}}"))
	if err != nil {
		t.Fatal(err)
	}
	o := v.Obj()
	if got := strings.Join(o.Keys(), ","); got != "a,b" {
		t.Fatalf("keys %s", got)
	}
	if o.Get("a").Kind() != Object {
		t.Fatalf("last duplicate should win")
	}
}

func TestLoneSurrogate(t *testing.T) {
	v, err := Parse([]byte(`["\ud800", "\udc00x", "\ud83d\ude00"]`))
	if err != nil {
		t.Fatal(err)
	}
	items := v.Items()
	for i, want := range []string{"\uFFFD", "\uFFFDx", "😀"} {
		if s, _ := items[i].Str(); s != want {
			t.Errorf("item %d = %q want %q", i, s, want)
		}
	}
}

func TestAccessors(t *testing.T) {
	v, err := Parse([]byte(`{"i": 6144, "neg": -1, "f": 1.0, "e": 1e3, "big": 99999999999999999999, "s": "x", "b": true, "n": null, "a": [1]}`))
	if err != nil {
		t.Fatal(err)
	}
	o := v.Obj()
	if i, ok := o.Get("i").Int(); !ok || i != 6144 {
		t.Errorf("i: %d %v", i, ok)
	}
	if i, ok := o.Get("neg").Int(); !ok || i != -1 {
		t.Errorf("neg: %d %v", i, ok)
	}
	for _, k := range []string{"f", "e", "big", "s", "b", "n", "a", "missing"} {
		if _, ok := o.Get(k).Int(); ok {
			t.Errorf("%s: Int ok", k)
		}
	}
	if f, ok := o.Get("e").Float(); !ok || f != 1000 {
		t.Errorf("e float %v %v", f, ok)
	}
	if lit, ok := o.Get("e").NumberLiteral(); !ok || lit != "1e3" {
		t.Errorf("literal %q", lit)
	}
	if s, ok := o.Get("s").Str(); !ok || s != "x" {
		t.Errorf("s")
	}
	if b, ok := o.Get("b").BoolVal(); !ok || !b {
		t.Errorf("b")
	}
	if o.Get("n").Kind() != Null || o.Get("missing").Kind() != Null || !o.Has("n") || o.Has("missing") {
		t.Errorf("null / missing")
	}
	if len(o.Get("a").Items()) != 1 || o.Get("s").Items() != nil || o.Get("s").Obj() != nil {
		t.Errorf("items / obj")
	}
	var nilObj *Obj
	if nilObj.Len() != 0 || nilObj.Get("x") != nil || nilObj.Has("x") || nilObj.Keys() != nil {
		t.Errorf("nil Obj")
	}
	nilObj.Delete("x")
}

func TestSetDeleteOrder(t *testing.T) {
	v := NewObject()
	o := v.Obj()
	o.Set("b", NewInt(1))
	o.Set("a", NewString("x"))
	o.Set("c", nil)
	o.Set("b", NewBool(false)) // in place
	o.Delete("a")
	o.Delete("zzz")
	o.Set("a", NewArray())
	want := "{\n  \"b\": false,\n  \"c\": null,\n  \"a\": []\n}"
	if got := string(v.MarshalPython()); got != want {
		t.Fatalf("got %q", got)
	}
	var zero Obj
	zero.Set("k", NewInt(-5))
	if zero.Len() != 1 || zero.Get("k").s != "-5" {
		t.Fatalf("zero Obj Set")
	}
}

func TestCloneIsDeep(t *testing.T) {
	v, _ := Parse([]byte(`{"a": {"b": [1, {"c": 2}]}}`))
	c := v.Clone()
	c.Obj().Get("a").Obj().Set("new", NewInt(1))
	c.Obj().Get("a").Obj().Get("b").Items()[1].Obj().Set("c", NewInt(3))
	if got := string(v.MarshalPython()); strings.Contains(got, "new") || strings.Contains(got, "3") {
		t.Fatalf("original changed: %s", got)
	}
}

func TestFromGoToGo(t *testing.T) {
	v, err := FromGo(map[string]any{
		"z": 1, "a": []any{true, nil, "s", 1.5, json.Number("1e3"), uint64(math.MaxUint64), int8(-3)},
		"m": map[string]any{}, "l": []string{"x"}, "f": 6144.0,
	})
	if err != nil {
		t.Fatal(err)
	}
	want := `{
  "a": [
    true,
    null,
    "s",
    1.5,
    1000.0,
    18446744073709551615,
    -3
  ],
  "f": 6144.0,
  "l": [
    "x"
  ],
  "m": {},
  "z": 1
}`
	if got := string(v.MarshalPython()); got != want {
		t.Fatalf("got %s", got)
	}
	if _, err := FromGo(struct{}{}); err == nil {
		t.Fatal("struct accepted")
	}
	if _, err := FromGo(json.Number("1.")); err == nil {
		t.Fatal("bad json.Number accepted")
	}
	if got, err := FromGo((*Value)(nil)); err != nil || got.Kind() != Null {
		t.Fatal("nil *Value")
	}
	o := NewObject().Obj()
	o.Set("k", NewInt(1))
	if got, _ := FromGo(o); got.Obj() != o {
		t.Fatal("*Obj not wrapped")
	}

	g := v.ToGo().(map[string]any)
	out, err := json.Marshal(g)
	if err != nil {
		t.Fatal(err)
	}
	// ToGo keeps the literal (json.Number "1e3"), only MarshalPython reformats it.
	if string(out) != `{"a":[true,null,"s",1.5,1e3,18446744073709551615,-3],"f":6144.0,"l":["x"],"m":{},"z":1}` {
		t.Fatalf("ToGo json: %s", out)
	}
	special, _ := Parse([]byte(`[NaN, Infinity]`))
	if out, err := json.Marshal(special.ToGo()); err != nil || string(out) != "[null,null]" {
		t.Fatalf("special ToGo: %s %v", out, err)
	}
}

func TestStringEscapes(t *testing.T) {
	got := string(NewString("a\"b\\c\x00\x1f\x7f\b\f\n\r\t中\u2028/\xff").MarshalPython())
	want := `"a\"b\\c\u0000\u001f` + "\x7f" + `\b\f\n\r\t中` + "\u2028" + `/` + "\uFFFD" + `"`
	if got != want {
		t.Fatalf("got %q want %q", got, want)
	}
}
